1:import { describe, expect, it } from "vitest";
2:import { salaryUsdMonthOf } from "./salary-usd.js";
3:
4:/**
5: * The denormalized `jobs.salary_usd_month` is what the jobs list filters and
6: * orders by ACROSS pages, so it has to agree with the scorer's own
7: * normalization (`monthlyUsdMax`) — same rates, same period rules, same
8: * refusal to guess an unknown currency.
9: */
10:describe("salaryUsdMonthOf", () => {
11:  it("normalizes a yearly USD range to its monthly ceiling", () => {
12:    expect(
13:      salaryUsdMonthOf({
14:        min: 96_000,
15:        max: 144_000,
16:        currency: "USD",
17:        period: "year",
18:      }),
19:    ).toBe(12_000);
20:  });
21:
22:  it("converts a BRL monthly range through the indicative rate", () => {
23:    expect(
24:      salaryUsdMonthOf({
25:        min: 8_000,
26:        max: 15_000,
27:        currency: "BRL",
28:        period: "month",
29:      }),
30:    ).toBeCloseTo(2_850, 0);
31:  });
32:
33:  it("returns null when nothing is listed or the currency is unknown", () => {
34:    expect(salaryUsdMonthOf(undefined)).toBeNull();
35:    expect(salaryUsdMonthOf({})).toBeNull();
36:    expect(
37:      salaryUsdMonthOf({ max: 50_000, currency: "PHP", period: "year" }),
38:    ).toBeNull();
39:  });
40:
41:  it("decides an unstated period by magnitude, on the raw amount", () => {
42:    expect(salaryUsdMonthOf({ max: 120_000, currency: "USD" })).toBe(10_000);
43:    expect(salaryUsdMonthOf({ max: 9_000, currency: "USD" })).toBe(9_000);
44:  });
45:});

