1:import type { SalaryInfo } from "@fbj/adapters";
2:import { monthlyUsdMax } from "@fbj/llm";
3:
4:/**
5: * `jobs.salary_usd_month` for a posting's salary block — the range ceiling in
6: * monthly USD, or null when nothing is listed or the currency is beyond the
7: * rate table. One call site per place the salary columns are written, so the
8: * denormalized column can never disagree with the fields it summarizes.
9: */
10:export function salaryUsdMonthOf(
11:  salary: SalaryInfo | null | undefined,
12:): number | null {
13:  if (!salary || (salary.min == null && salary.max == null)) return null;
14:  return monthlyUsdMax({
15:    salaryMin: salary.min ?? null,
16:    salaryMax: salary.max ?? null,
17:    salaryCurrency: salary.currency ?? null,
18:    salaryPeriod: salary.period ?? null,
19:  } as Parameters<typeof monthlyUsdMax>[0]);
20:}
